class Cache<K, V> {
    private final Map<K, V> map = new HashMap<>();
    private final java.util.function.Function<K, V> loader;
    int loads = 0;
    Cache(java.util.function.Function<K, V> loader) { this.loader = loader; }
    V get(K key) {
        return map.computeIfAbsent(key, k -> { loads++; return loader.apply(k); });
    }
}
