class Stack<E> {
    private final Deque<E> d = new ArrayDeque<>();
    void push(E e) { d.push(e); }
    E pop() { return d.pop(); }
    void pushAll(Iterable<? extends E> src) { for (E e : src) push(e); }
    void popAll(Collection<? super E> dst) { while (!d.isEmpty()) dst.add(pop()); }
}
